def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)

def minPath(grid, k):
    from collections import deque

    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None

    # BFS to explore all paths starting from each cell
    for start_row in range(n):
        for start_col in range(n):
            queue = deque([(start_row, start_col, [grid[start_row][start_col]])])
            while queue:
                row, col, path = queue.popleft()
                if len(path) == k:
                    # Update the minimum path if this one is smaller
                    if min_path is None or path < min_path:
                        min_path = path
                    continue
                for dr, dc in directions:
                    new_row, new_col = row + dr, col + dc
                    if 0 <= new_row < n and 0 <= new_col < n:
                        queue.append((new_row, new_col, path + [grid[new_row][new_col]]))

    return min_path

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        if i % 4 == 0 and i % 3 != 0:
            total += value ** 3
        if i % 3 != 0 and i % 4 != 0:
            total += value
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def x_or_y(n, x, y):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
